'use strict';
// Test suite for the shout CLI (cli.js). Zero-dep: node assert + child_process.
const { spawnSync } = require('child_process');
const assert = require('assert');
const path = require('path');

const CLI = path.join(__dirname, '..', 'cli.js');

function run(args) {
  const r = spawnSync(process.execPath, [CLI, ...args], { encoding: 'utf8' });
  return { status: r.status, stdout: r.stdout, stderr: r.stderr };
}

let passed = 0;
let failed = 0;

function test(name, fn) {
  try {
    fn();
    passed++;
    console.log(`ok - ${name}`);
  } catch (e) {
    failed++;
    console.error(`FAIL - ${name}: ${e.message}`);
  }
}

// Repeat 3 -> exactly 3 lines, each "HI"
test('--upper --repeat 3 hi prints 3 lines', () => {
  const r = run(['--upper', '--repeat', '3', 'hi']);
  assert.strictEqual(r.status, 0);
  assert.strictEqual(r.stdout, 'HI\nHI\nHI\n');
});

// Repeat 1 -> exactly 1 line
test('--upper --repeat 1 hi prints 1 line', () => {
  const r = run(['--upper', '--repeat', '1', 'hi']);
  assert.strictEqual(r.status, 0);
  assert.strictEqual(r.stdout, 'HI\n');
});

// Non-numeric N -> non-zero exit, message on stderr
test('--repeat banana exits non-zero', () => {
  const r = run(['--upper', '--repeat', 'banana', 'hi']);
  assert.notStrictEqual(r.status, 0);
  assert.ok(/error/i.test(r.stderr));
});

// Zero N -> non-zero exit
test('--repeat 0 exits non-zero', () => {
  const r = run(['--repeat', '0', 'hi']);
  assert.notStrictEqual(r.status, 0);
});

// Negative N -> non-zero exit
test('--repeat -3 exits non-zero', () => {
  const r = run(['--repeat', '-3', 'hi']);
  assert.notStrictEqual(r.status, 0);
});

// Missing --repeat value -> non-zero exit
test('--repeat with no value exits non-zero', () => {
  const r = run(['--repeat']);
  assert.notStrictEqual(r.status, 0);
});

// --upper alone still works (backwards compatible), one line
test('--upper without --repeat still works', () => {
  const r = run(['--upper', 'hello']);
  assert.strictEqual(r.status, 0);
  assert.strictEqual(r.stdout, 'HELLO\n');
});

// Flag order is arbitrary
test('--repeat 3 --upper hi equals --upper --repeat 3 hi', () => {
  const a = run(['--upper', '--repeat', '3', 'hi']);
  const b = run(['--repeat', '3', '--upper', 'hi']);
  assert.strictEqual(a.stdout, b.stdout);
  assert.strictEqual(a.stdout, 'HI\nHI\nHI\n');
});

// Without --upper, text is echoed, repeated
test('--repeat 2 hello echoes hello twice', () => {
  const r = run(['--repeat', '2', 'hello']);
  assert.strictEqual(r.status, 0);
  assert.strictEqual(r.stdout, 'hello\nhello\n');
});

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed === 0 ? 0 : 1);

